/**
 * Native addon surface.
 *
 * Generated by `wae build types` from the addon's `__waeTypes` metadata.
 * Do not edit: change the Rust `#[function]` / `#[object]` definitions and
 * rebuild instead. The step runs before `ts`, so the compiled surface always
 * matches the addon that was just built.
 */

import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);

/** Runtime target (`<platform>-<arch>`) → platform package that carries the addon. */
const ADDONS: Record<string, string> = {
    'win32-x64': '@wae/{{name}}-win32-x64',
};

export interface ActorRequest {
    actorKind?: string
    actorId?: string
    actorSource?: string
    session?: string
    host?: string
}

export interface AuditRequest {
    kind?: string
    id?: string
    capability?: string
    fromMs?: number
    toMs?: number
    limit?: number
}

export interface GuiRequest {
    contentDir?: string
    title?: string
}

export interface InspectRequest {
    root?: string
    limit?: number
}

export interface InstallRequest {
    noShortcut?: boolean
    resetConfig?: boolean
}

export interface OkResult {
    ok: boolean
}

export interface OpenedWindow {
    backend: string
}

export interface UninstallRequest {
    keepConfig?: boolean
}

/** Raw surface exported by the Rust addon. */
export interface NativeModule {
    auditQuery(request?: AuditRequest): string;
    capabilities(): unknown;
    closeGui(): boolean;
    configureAudit(request?: ActorRequest): OkResult;
    inspect(request?: InspectRequest): unknown;
    installApply(request?: InstallRequest): OkResult;
    installPlan(request?: InstallRequest): unknown;
    isGuiOpen(): boolean;
    openGui(request?: GuiRequest): OpenedWindow;
    pumpEvents(): boolean;
    uninstallApply(request?: UninstallRequest): OkResult;
    uninstallPlan(request?: UninstallRequest): unknown;
    version(): string;
}

let cached: NativeModule | null = null;

/** Load the addon for the current process; throws when the platform package is missing. */
export function loadNative(): NativeModule {
    if (cached !== null) return cached;
    const key = `${process.platform}-${process.arch}`;
    const packageName = ADDONS[key];
    if (packageName === undefined) {
        throw new Error(`no native addon is published for \`${key}\` (supported: ${Object.keys(ADDONS).join(', ')})`);
    }
    try {
        cached = require(packageName) as NativeModule;
        return cached;
    }
    catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        throw new Error(`cannot load ${packageName} for \`${key}\`: ${message}`);
    }
}

/** Exported by the Rust addon. */
export function auditQuery(request?: AuditRequest): string {
    return loadNative().auditQuery(request);
}

/** Exported by the Rust addon. */
export function capabilities(): unknown {
    return loadNative().capabilities();
}

/** Exported by the Rust addon. */
export function closeGui(): boolean {
    return loadNative().closeGui();
}

/** Exported by the Rust addon. */
export function configureAudit(request?: ActorRequest): OkResult {
    return loadNative().configureAudit(request);
}

/** Exported by the Rust addon. */
export function inspect(request?: InspectRequest): unknown {
    return loadNative().inspect(request);
}

/** Exported by the Rust addon. */
export function installApply(request?: InstallRequest): OkResult {
    return loadNative().installApply(request);
}

/** Exported by the Rust addon. */
export function installPlan(request?: InstallRequest): unknown {
    return loadNative().installPlan(request);
}

/** Exported by the Rust addon. */
export function isGuiOpen(): boolean {
    return loadNative().isGuiOpen();
}

/** Exported by the Rust addon. */
export function openGui(request?: GuiRequest): OpenedWindow {
    return loadNative().openGui(request);
}

/** Exported by the Rust addon. */
export function pumpEvents(): boolean {
    return loadNative().pumpEvents();
}

/** Exported by the Rust addon. */
export function uninstallApply(request?: UninstallRequest): OkResult {
    return loadNative().uninstallApply(request);
}

/** Exported by the Rust addon. */
export function uninstallPlan(request?: UninstallRequest): unknown {
    return loadNative().uninstallPlan(request);
}

/** Exported by the Rust addon. */
export function version(): string {
    return loadNative().version();
}
